      "content": "// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import {IStrategy, IStrategyDustReceiver} from "../../../interfaces/core/IStrategy.sol";
import {IStrategyManager} from "../../../interfaces/core/IStrategyManager.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {IEventEmitter} from "../../../interfaces/core/IEventEmitter.sol";
import {SafeERC20Upgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC20/utils/SafeERC20Upgradeable.sol";
import {FunctionParameters} from "../../../library/core/FunctionParameters.sol";
import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import {IBGTGauge} from "../../../interfaces/external/bera/IBGTGauge.sol";
import {IBendVault} from "../../../interfaces/strategy/IBendVault.sol";
import {IUniversalRewardDistributor} from "../../../interfaces/strategy/IUniversalRewardDistributor.sol";
import {IERC20Upgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC20/IERC20Upgradeable.sol";
import {ErrorLibrary} from "../../../library/core/ErrorLibrary.sol";
import {IProtocolRegistry} from "../../../interfaces/core/IProtocolRegistry.sol";
import {IKodiakSwapController} from "../../../interfaces/strategy/IKodiakSwapController.sol";

/**
 * @title HubStrategyBend
 * @notice Manages interaction between the protocol, Bend MetaMorpho vaults, and Hub staking
 * @dev Deposits underlying tokens into a Bend MetaMorpho vault (ERC4626), then stakes the
 *      vault shares in a Hub vault to earn WBERA rewards. Rewards from Hub are
 *      swapped back to the underlying token and re-deposited to compound returns.
 *      Bend URD rewards can also be claimed separately via merkle proofs.
 */
contract HubStrategyBend is
    Initializable,
    ReentrancyGuardUpgradeable,
    IStrategy,
    UUPSUpgradeable,
    OwnableUpgradeable
{
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    using SafeERC20Upgradeable for IERC20Upgradeable;

    address public constant WBERA = 0x6969696969696969696969696969696969696969;

    /************/
    /* Constants */
    /************/

    uint256 public constant MAX_SLIPPAGE = 10000; // 100% in basis points

    /************/
    /* Storage */
    /************/

    /// @notice Address of the strategy manager
    address public strategyManager;

    /// @notice Name of the strategy
    string public name;

    /// @notice Address of the underlying token (e.g. HONEY)
    address public underlyingToken;

    /// @notice Address of the Bend MetaMorpho vault (ERC4626)
    address public bendVault;

    /// @notice Address of the Hub vault for staking Bend vault shares
    address public hubVault;

    /// @notice Protocol registry contract
    IProtocolRegistry public protocolRegistry;

    /// @notice Address of the Kodiak swap router for reward swaps
    address public kodiakSwapRouter;

    /// @notice Fee tier for Kodiak swaps
    uint256 public fee;

    /// @notice Address of the Bend Universal Reward Distributor (URD)
    address public urdRewardsDistributor;

    /// @notice Mapping of valid reward tokens for URD claims
    mapping(address => bool) public rewardTokens;

    // ── Reward swap routing (appended for upgrade — keep at end of storage) ──
    /// @notice When set, getReward swaps each reward token to underlyingToken via
    ///         rewardToken -> rewardIntermediaryToken -> underlyingToken instead of
    ///         a direct pool (used when no liquid direct pool exists, e.g. iBGT/HONEY).
    address public rewardIntermediaryToken;
    /// @notice Pool fee tier for the rewardToken -> intermediary leg
    uint24 public rewardFeeIn;
    /// @notice Pool fee tier for the intermediary -> underlyingToken leg
    uint24 public rewardFeeOut;

    /************/
    /* Modifiers */
    /************/

    modifier onlyStrategyManager() {
        if (msg.sender != strategyManager) revert ErrorLibrary.CallerIsNotStrategyManager();
        _;
    }

    modifier whenNotPaused() {
        if (protocolRegistry.getProtocolState()) revert ErrorLibrary.ProtocolPaused();
        _;
    }

    modifier validSlippage(uint256 _slippage) {
        if (_slippage > MAX_SLIPPAGE) revert ErrorLibrary.InvalidSlippage();
        _;
    }

    modifier onlyRewardsClaimer() {
        if (msg.sender != protocolRegistry.getRewardsClaimer()) revert ErrorLibrary.CallerIsNotRewardsClaimer();
        _;
    }

    /*************/
    /* Initialization */
    /*************/

    /**
     * @notice Initializes the strategy
     * @param _underlyingToken Address of the underlying token
     * @param _bendVault Address of the Bend MetaMorpho vault
     * @param _hubVault Address of the Hub vault
     * @param _name Name of the strategy
     * @param _protocolRegistry Address of the protocol registry
     * @param _kodiakSwapRouter Address of the Kodiak swap router
     * @param _fee Fee tier for Kodiak swaps
     * @param _urdRewardsDistributor Address of the Bend URD
     * @param _rewardTokens Array of valid reward token addresses for URD
     */
    function initialize(
        address _underlyingToken,
        address _bendVault,
        address _hubVault,
        string memory _name,
        address _protocolRegistry,
        address _kodiakSwapRouter,
        uint256 _fee,
        address _urdRewardsDistributor,
        address[] memory _rewardTokens
    ) public initializer {
        if (_underlyingToken == address(0)) revert ErrorLibrary.InvalidAddress();
        if (_bendVault == address(0)) revert ErrorLibrary.InvalidAddress();
        if (_hubVault == address(0)) revert ErrorLibrary.InvalidAddress();
        if (_protocolRegistry == address(0)) revert ErrorLibrary.InvalidAddress();
        if (_kodiakSwapRouter == address(0)) revert ErrorLibrary.InvalidAddress();
        if (_urdRewardsDistributor == address(0)) revert ErrorLibrary.InvalidAddress();
        if (_fee > type(uint24).max || _fee == 0) revert ErrorLibrary.InvalidFee();

        ReentrancyGuardUpgradeable.__ReentrancyGuard_init();
        __UUPSUpgradeable_init();
        __Ownable_init();

        underlyingToken = _underlyingToken;
        bendVault = _bendVault;
        hubVault = _hubVault;
        name = _name;
        protocolRegistry = IProtocolRegistry(_protocolRegistry);
        kodiakSwapRouter = _kodiakSwapRouter;
        fee = _fee;
        urdRewardsDistributor = _urdRewardsDistributor;
        updateRewardToken(_rewardTokens);
    }

    /**************************/
    /* External State-Changing Functions */
    /**************************/

    /**
     * @notice Deposits underlying tokens into Bend vault then stakes shares in Hub
     * @param _amount Amount of underlying tokens to deposit
     * @param _slippage Maximum allowed slippage
     * @param _lpSlippage Maximum allowed LP slippage
     * @return Amount of underlying tokens deposited and dust amount
     */
    function deposit(
        uint256 _amount,
        uint256 _slippage,
        uint256 _lpSlippage
    )
        public
        onlyStrategyManager
        nonReentrant
        whenNotPaused
        validSlippage(_slippage)
        validSlippage(_lpSlippage)
        returns (uint256, uint256)
    {
        if (_amount == 0) revert ErrorLibrary.InvalidAmount();
        IERC20Upgradeable(underlyingToken).safeTransferFrom(msg.sender, address(this), _amount);
        (uint256 amount, uint256 dustAmount) = _deposit(_amount);
        IEventEmitter(protocolRegistry.getEventEmitter()).strategyDepositSuccessEvent(address(this), amount);
        return (amount, dustAmount);
    }

    /**
     * @notice Restricts base-token deposits to protocol-internal callers
     * @dev M-13: depositBase was permissionless, letting anyone donate into the
     *      strategy and inflate its reported NAV (feeding the share-price and
     *      recapitalization findings). Legitimate callers are the strategy manager,
     *      a sibling strategy routing its dust here, and the rewards claimer that
     *      compounds harvested rewards.
     */
    modifier onlyProtocolDepositor() {
        if (
            msg.sender != strategyManager &&
            msg.sender != protocolRegistry.getRewardsClaimer() &&
            !protocolRegistry.verifyProtocolStrategyAddress(msg.sender)
        ) revert ErrorLibrary.CallerIsNotStrategyManager();
        _;
    }

    /**
     * @notice Permissionless deposit entry used to forward auto-compounded dust without the
     *         StrategyManager round-trip. Caller must hold `underlyingToken` and have approved
     *         this contract for `_amount`.
     */
    function depositBase(uint256 _amount) external nonReentrant whenNotPaused onlyProtocolDepositor {
        if (_amount == 0) revert ErrorLibrary.InvalidAmount();
        IERC20Upgradeable(underlyingToken).safeTransferFrom(msg.sender, address(this), _amount);
        _deposit(_amount);
    }

    /**
     * @notice Withdraws by unstaking from Hub, redeeming from Bend, and returning underlying
     * @param _params Withdrawal parameters
     * @param _slippage Maximum allowed slippage
     * @param _lpSlippage Maximum allowed LP slippage
     */
    function withdraw(
        FunctionParameters.StrategyWithdrawParams memory _params,
        uint256 _slippage,
        uint256 _lpSlippage
    ) public onlyStrategyManager nonReentrant whenNotPaused validSlippage(_slippage) validSlippage(_lpSlippage) {
        uint256 balance = getUnderlyingBalance();
        if (balance == 0) revert ErrorLibrary.InvalidAmount();
        // Unstake Bend vault shares from Hub
        unstake(_params.strategyTokenAmount);
        // Redeem the exact unstaked share amount. Asset-denominated withdraw
        // can round up to N+1 shares and revert after only N shares were unstaked.
        _withdraw(_params.strategyTokenAmount);
    }

    /**
     * @notice Claims and compounds Hub WBERA rewards
     * @dev Claims rewards from Hub vault, swaps non-underlying tokens via Kodiak,
     *      then re-deposits all accumulated underlying tokens to compound returns.
     * @param _slippage Maximum allowed slippage for reward swaps
     */
    function getReward(
        uint256 _slippage
    ) external nonReentrant whenNotPaused onlyRewardsClaimer validSlippage(_slippage) {
        _harvest(_slippage);
    }

    /**
     * @notice Uniform harvest entry point called by the StrategyManager during
     *         _updateInvestment, so pending rewards are compounded into the
     *         balance before the vault reads it.
     * @dev `_lpSlippage` is unused here: this strategy has no LP leg. Guarded by
     *      onlyStrategyManager in addition to the claimer path above.
     */
    function harvest(uint256 _slippage, uint256 _lpSlippage) external nonReentrant whenNotPaused validSlippage(_slippage) {
        if (msg.sender != strategyManager && msg.sender != protocolRegistry.getRewardsClaimer())
            revert ErrorLibrary.CallerIsNotStrategyManager();
        _harvest(_slippage);
    }

    /// @dev Shared body. Internal so both entry points reuse it without
    ///      re-entering the contract's own nonReentrant guard.
    function _harvest(uint256 _slippage) internal {
        if (_slippage > 300) revert ErrorLibrary.InvalidSlippage();
        address[] memory HubRewardTokens = new address[](1);
        HubRewardTokens[0] = WBERA;
        IBGTGauge(hubVault).getReward(address(this), address(this));

        uint256 totalUnderlyingTokenAmount = 0;
        uint256[] memory rewardAmounts = new uint256[](HubRewardTokens.length);

        for (uint256 i = 0; i < HubRewardTokens.length; i++) {
            uint256 balance = IERC20Upgradeable(HubRewardTokens[i]).balanceOf(address(this));
            if (balance == 0) continue;

            rewardAmounts[i] = balance;

            if (HubRewardTokens[i] == underlyingToken) {
                totalUnderlyingTokenAmount += balance;
            } else {
                IERC20Upgradeable(HubRewardTokens[i]).safeApprove(kodiakSwapRouter, 0);
                IERC20Upgradeable(HubRewardTokens[i]).safeApprove(kodiakSwapRouter, balance);

                uint256 underlyingTokenReceived;
                if (rewardIntermediaryToken == address(0)) {
                    // Direct single-hop swap rewardToken -> underlyingToken.
                    underlyingTokenReceived = IKodiakSwapController(kodiakSwapRouter).swap(
                        HubRewardTokens[i],
                        underlyingToken,
                        balance,
                        uint24(fee),
                        _slippage
                    );
                } else {
                    // Multi-hop swap rewardToken -> intermediary -> underlyingToken (no liquid direct pool).
                    underlyingTokenReceived = IKodiakSwapController(kodiakSwapRouter).swapWithIntermediary(
                        HubRewardTokens[i],
                        rewardIntermediaryToken,
                        underlyingToken,
                        balance,
                        rewardFeeIn,
                        rewardFeeOut,
                        _slippage
                    );
                }
                totalUnderlyingTokenAmount += underlyingTokenReceived;
            }
        }

        // Compound rewards back into this strategy. Any residual underlying (typically 0 for
        // this single-asset path) is forwarded into the configured dust strategy via depositBase.
        uint256 receiptTokenAmount = 0;
        uint256 dustAmount = 0;
        if (totalUnderlyingTokenAmount > 0) {
            uint256 HubBalanceBefore = IBGTGauge(hubVault).balanceOf(address(this));
            _deposit(totalUnderlyingTokenAmount);
            receiptTokenAmount = IBGTGauge(hubVault).balanceOf(address(this)) - HubBalanceBefore;

            dustAmount = IERC20Upgradeable(underlyingToken).balanceOf(address(this));
            if (dustAmount > 0) {
                address dustStrategy = IStrategyManager(strategyManager).dustStrategy();
                if (dustStrategy == address(0)) revert ErrorLibrary.InvalidAddress();
                IERC20Upgradeable(underlyingToken).safeApprove(dustStrategy, 0);
                IERC20Upgradeable(underlyingToken).safeApprove(dustStrategy, dustAmount);
                IStrategyDustReceiver(dustStrategy).depositBase(dustAmount);
            }
        }

        IEventEmitter(protocolRegistry.getEventEmitter()).strategyRewardClaimedEvent(
            address(this),
            HubRewardTokens,
            rewardAmounts,
            totalUnderlyingTokenAmount,
            receiptTokenAmount,
            dustAmount
        );
    }

    /**
     * @notice Claims rewards from the Bend Universal Reward Distributor (URD)
     * @dev URD uses merkle proofs for reward distribution. Each reward token is claimed
     *      individually and forwarded to the protocol's reward distributor.
     * @param _rewardTokenAddresses Array of reward token addresses to claim
     * @param _claimableAmounts Array of claimable amounts for each token
     * @param _proofs Array of merkle proofs for each claim
     */
    function claimUrdReward(
        address[] memory _rewardTokenAddresses,
        uint256[] memory _claimableAmounts,
        bytes32[][] memory _proofs
    ) external onlyRewardsClaimer {
        for (uint256 i = 0; i < _rewardTokenAddresses.length; i++) {
            if (!rewardTokens[_rewardTokenAddresses[i]]) revert ErrorLibrary.TokenNotRewardToken();

            IUniversalRewardDistributor(urdRewardsDistributor).claim(
                address(this),
                _rewardTokenAddresses[i],
                _claimableAmounts[i],
                _proofs[i]
            );

            uint256 rewardBalance = IERC20Upgradeable(_rewardTokenAddresses[i]).balanceOf(address(this));
            if (rewardBalance > 0) {
                IERC20Upgradeable(_rewardTokenAddresses[i]).safeTransfer(
                    protocolRegistry.getRewardDistributor(),
                    rewardBalance
                );
            }
        }

        IEventEmitter(protocolRegistry.getEventEmitter()).strategyRewardClaimedEvent(
            address(this),
            _rewardTokenAddresses,
            _claimableAmounts,
            0,
            0,
            0
        );
    }

    /**************************/
    /* View Functions */
    /**************************/

    /**
     * @notice Gets the Hub vault staked balance (in Bend vault shares)
     * @return Balance of staked Bend vault shares
     */
    function getTokenBalance() public view returns (uint256) {
        return IBGTGauge(hubVault).balanceOf(address(this));
    }

    /**
     * @notice Gets the underlying token balance by converting staked shares to assets
     * @return Underlying token balance
     */
    function getUnderlyingBalance() public view returns (uint256) {
        return _getUnderlyingBalance(getTokenBalance());
    }

    /**
     * @notice Gets the reward token address
     * @return Address of the underlying token
     */
    function rewardToken() public view returns (address) {
        return underlyingToken;
    }

    /******************************/
    /* Admin Functions */
    /******************************/

    /**
     * @notice Sets the strategy manager address
     * @param _strategyManager Address of the strategy manager
     */
    function setStrategyManager(address _strategyManager) public onlyOwner {
        if (_strategyManager == address(0)) revert ErrorLibrary.InvalidAddress();
        strategyManager = _strategyManager;
    }

    /**
     * @notice Updates the Kodiak swap fee tier
     * @param _fee New fee tier
     */
    function updateFee(uint256 _fee) external onlyOwner {
        if (_fee > type(uint24).max || _fee == 0) revert ErrorLibrary.InvalidFee();
        fee = _fee;
    }

    /**
     * @notice Configures the multi-hop reward swap route (rewardToken -> intermediary -> underlyingToken).
     * @dev When set, getReward routes reward swaps through `_intermediary` instead of the direct pool.
     *      Both fee tiers must be non-zero. Use `clearRewardIntermediary` to revert to direct swaps.
     * @param _intermediary Intermediary hop token (e.g. WBERA)
     * @param _feeIn Pool fee tier for the rewardToken -> intermediary leg
     * @param _feeOut Pool fee tier for the intermediary -> underlyingToken leg
     */
    function setRewardIntermediary(address _intermediary, uint24 _feeIn, uint24 _feeOut) external onlyOwner {
        if (_intermediary == address(0)) revert ErrorLibrary.InvalidAddress();
        if (_feeIn == 0 || _feeOut == 0) revert ErrorLibrary.InvalidFee();
        rewardIntermediaryToken = _intermediary;
        rewardFeeIn = _feeIn;
        rewardFeeOut = _feeOut;
    }

    /**
     * @notice Clears the multi-hop reward route so getReward falls back to direct single-hop swaps.
     */
    function clearRewardIntermediary() external onlyOwner {
        rewardIntermediaryToken = address(0);
        rewardFeeIn = 0;
        rewardFeeOut = 0;
    }

    /**
     * @notice Updates the list of valid reward tokens for URD claims
     * @param _rewardTokens Array of reward token addresses to whitelist
     */
    function updateRewardToken(address[] memory _rewardTokens) public onlyOwner {
        for (uint256 i = 0; i < _rewardTokens.length; i++) {
            if (_rewardTokens[i] == address(0)) revert ErrorLibrary.InvalidAddress();
            rewardTokens[_rewardTokens[i]] = true;
        }
    }

    /**
     * @notice Updates the URD rewards distributor address
     * @param _urdRewardsDistributor New URD address
     */
    function setUrdRewardsDistributor(address _urdRewardsDistributor) external onlyOwner {
        if (_urdRewardsDistributor == address(0)) revert ErrorLibrary.InvalidAddress();
        urdRewardsDistributor = _urdRewardsDistributor;
    }

    /*****************************/
    /* Internal Helper Functions */
    /*****************************/

    /**
     * @notice Deposits underlying into Bend vault and stakes resulting shares in Hub
     * @param _amount Amount of underlying tokens to deposit
     * @return Amount of underlying deposited and dust (always 0)
     */
    function _deposit(uint256 _amount) internal returns (uint256, uint256) {
        if (_amount == 0) revert ErrorLibrary.InvalidAmount();

        // Deposit underlying into Bend MetaMorpho vault to get shares
        IERC20Upgradeable(underlyingToken).safeApprove(bendVault, 0);
        IERC20Upgradeable(underlyingToken).safeApprove(bendVault, _amount);

        uint256 sharesBefore = IERC20Upgradeable(bendVault).balanceOf(address(this));
        uint256 balanceAssetsBefore = _getUnderlyingBalance(IBGTGauge(hubVault).balanceOf(address(this)));

        IBendVault(bendVault).deposit(_amount, address(this));

        uint256 sharesAfter = IERC20Upgradeable(bendVault).balanceOf(address(this));
        uint256 newShares = sharesAfter - sharesBefore;

        // Stake the new Bend vault shares into Hub
        stake(newShares);

        uint256 balanceAssetsAfter = _getUnderlyingBalance(IBGTGauge(hubVault).balanceOf(address(this)));
        return (balanceAssetsAfter - balanceAssetsBefore, 0);
    }

    /**
     * @notice Redeems underlying from Bend vault and transfers to caller
     * @param _amount Amount of Bend vault shares to redeem
     */
    function _withdraw(uint256 _amount) internal {
        if (_amount == 0) revert ErrorLibrary.InvalidAmount();

        IBendVault(bendVault).redeem(_amount, address(this), address(this));
        uint256 balance = IERC20Upgradeable(underlyingToken).balanceOf(address(this));
        IERC20Upgradeable(underlyingToken).safeTransfer(msg.sender, balance);
        IEventEmitter(protocolRegistry.getEventEmitter()).strategyWithdrawSuccessEvent(address(this), balance);
    }

    /**
     * @notice Stakes Bend vault shares into the Hub vault
     * @param _amount Amount of shares to stake
     */
    function stake(uint256 _amount) internal {
        IERC20Upgradeable(bendVault).safeApprove(address(hubVault), 0);
        IERC20Upgradeable(bendVault).safeApprove(address(hubVault), _amount);
        IBGTGauge(hubVault).stake(_amount);
    }

    /**
     * @notice Unstakes Bend vault shares from the Hub vault
     * @param _amount Amount of shares to unstake
     */
    function unstake(uint256 _amount) internal {
        IBGTGauge(hubVault).withdraw(_amount);
    }

    /**
     * @notice Converts Bend vault shares to underlying asset amount
     * @param _amount Amount of shares
     * @return Equivalent underlying token amount
     */
    function _getUnderlyingBalance(uint256 _amount) internal view returns (uint256) {
        return IBendVault(bendVault).convertToAssets(_amount);
    }

    /**
     * @notice Authorizes contract upgrade
     * @param newImplementation Address of the new implementation
     */
    function _authorizeUpgrade(address newImplementation) internal virtual override onlyOwner {}
}
"
    },
    "contracts/interfaces/strategy/IKodiakSwapController.sol": {
      "content": "pragma solidity 0.8.30;

interface IKodiakSwapController {
    function swap(
        address _tokenIn,
        address _tokenOut,
        uint256 _amountIn,
        uint24 _fee,
        uint256 _slippage
    ) external returns (uint256 amountOut);

    function swapWithIntermediary(
        address _tokenIn,
        address _intermediary,
        address _tokenOut,
        uint256 _amountIn,
        uint24 _feeIn,
        uint24 _feeOut,
        uint256 _slippage
    ) external returns (uint256 amountOut);

    function getSlippage(
        uint256 _amount,
        uint256 _slippage,
        address[] memory path
    ) external view returns (uint256 minAmount);

    function getETH() external view returns (address);
}
"
    },
    "contracts/interfaces/core/IProtocolRegistry.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

interface IProtocolRegistry {
    function setProtocolPause(bool _state) external;
    function updateWETH(address _newWETH) external;
    function getProtocolState() external view returns (bool);
    function getETH() external view returns (address);
    function verifyProtocolStrategyAddress(address _strategyAddress) external view returns (bool);
    function verifyProtocolRedistributorAddress(address _strategyAddress) external view returns (bool);
    function getProtocolFee() external view returns (uint256);
    function setProtocolFee(uint256 _protocolFee) external;
    function getProtocolTreasury() external view returns (address);
    function setProtocolTreasury(address _protocolTreasury) external;
    function getOracle() external view returns (address);
    function setOracle(address _oracle) external;
    function getHoneyFactory() external view returns (address);
    function setHoneyFactory(address _honeyFactory) external;
    function getRewardDistributor() external view returns (address);
    function setRewardDistributor(address _rewardDistributor) external;
    function getEventEmitter() external view returns (address);
    function setEventEmitter(address _eventEmitter) external;
    function getRewardsClaimer() external view returns (address);
    function setRewardsClaimer(address _rewardsClaimer) external;
    function getStrategyPauseState(address _strategyAddress) external view returns (bool);
    function updateStrategyPauseState(address _strategyAddress, bool _isPaused) external;
    function setProtocolStrategyAddress(address[] calldata _strategyAddresses) external;
    function removeProtocolStrategyAddress(address[] calldata _strategyAddresses) external;
}
