    "contracts/interfaces/strategy/IBendVault.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

/**
 * @title IBendVault
 * @notice Interface for Bend MetaMorpho vaults (ERC4626 compliant)
 * @dev Bend is built on Morpho V1 and uses MetaMorpho vaults for lending
 */
interface IBendVault {
    /// @notice Deposits underlying assets into the vault and mints shares
    /// @param assets Amount of underlying assets to deposit
    /// @param receiver Address to receive the minted shares
    /// @return shares Amount of shares minted
    function deposit(uint256 assets, address receiver) external returns (uint256 shares);

    /// @notice Withdraws underlying assets from the vault by burning shares
    /// @param assets Amount of underlying assets to withdraw
    /// @param receiver Address to receive the withdrawn assets
    /// @param owner Address whose shares will be burned
    /// @return shares Amount of shares burned
    function withdraw(uint256 assets, address receiver, address owner) external returns (uint256 shares);

    /// @notice Redeems shares for underlying assets
    /// @param shares Amount of shares to redeem
    /// @param receiver Address to receive the underlying assets
    /// @param owner Address whose shares will be redeemed
    /// @return assets Amount of underlying assets received
    function redeem(uint256 shares, address receiver, address owner) external returns (uint256 assets);

    /// @notice Returns the share balance of an account
    /// @param account Address to query
    /// @return Share balance
    function balanceOf(address account) external view returns (uint256);

    /// @notice Converts share amount to underlying asset amount
    /// @param shares Amount of shares to convert
    /// @return assets Equivalent amount of underlying assets
    function convertToAssets(uint256 shares) external view returns (uint256 assets);

    /// @notice Converts underlying asset amount to share amount
    /// @param assets Amount of underlying assets to convert
    /// @return shares Equivalent amount of shares
    function convertToShares(uint256 assets) external view returns (uint256 shares);

    /// @notice Returns the total amount of underlying assets held by the vault
    /// @return Total underlying assets
    function totalAssets() external view returns (uint256);

    /// @notice Returns the total supply of shares
    /// @return Total shares
    function totalSupply() external view returns (uint256);

    /// @notice Returns the address of the underlying asset token
    /// @return Address of the underlying token
    function asset() external view returns (address);

    /// @notice Returns the maximum amount of assets that can be deposited
    /// @param receiver Address of the receiver
    /// @return Maximum deposit amount
    function maxDeposit(address receiver) external view returns (uint256);

    /// @notice Returns the maximum amount of assets that can be withdrawn
    /// @param owner Address of the share owner
    /// @return Maximum withdrawable amount
    function maxWithdraw(address owner) external view returns (uint256);

    /// @notice Returns the maximum amount of shares that can be redeemed
    /// @param owner Address of the share owner
    /// @return Maximum redeemable shares
    function maxRedeem(address owner) external view returns (uint256);
}
"
